-- Theme picker: lists the themes in lua/theme-data.lua (generated by
-- chezmoi from .chezmoidata/). Moving through the list previews each theme
-- live; <Esc> restores the original. Selecting one keeps it and runs
-- `theme-sync`, which re-applies WezTerm/starship/fzf/eza and recolors any
-- other running nvim instances.

-- Absolute paths: a GUI-launched nvim may not have ~/.local/bin on PATH.
-- On Windows, prefer PowerShell 7 (pwsh), falling back to Windows
-- PowerShell 5.1; theme-sync.ps1 works under both.
local function sync_cmd(slug)
	if vim.fn.has("win32") == 1 then
		local host = vim.fn.executable("pwsh") == 1 and "pwsh" or "powershell"
		return { host, "-NoProfile", "-File", vim.fn.expand("~/.local/bin/theme-sync.ps1"), slug }
	end
	return { vim.fn.expand("~/.local/bin/theme-sync"), slug }
end

local function run_theme_sync(slug, name)
	local stderr = {}
	vim.fn.jobstart(sync_cmd(slug), {
		stderr_buffered = true,
		on_stderr = function(_, data)
			stderr = data
		end,
		on_exit = function(_, code)
			if code == 0 then
				vim.notify("Theme set to " .. name)
			else
				local detail = vim.trim(table.concat(stderr, "\n"))
				vim.notify("theme-sync failed for " .. name .. (detail ~= "" and (":\n" .. detail) or ""), vim.log.levels.ERROR)
			end
		end,
	})
end

local function pick_theme()
	local pickers = require("telescope.pickers")
	local finders = require("telescope.finders")
	local previewers = require("telescope.previewers")
	local conf = require("telescope.config").values
	local actions = require("telescope.actions")
	local action_state = require("telescope.actions.state")
	local theme = require("theme")

	local data = theme.data(true) -- pick up themes added since startup
	local original = theme.current or data.current
	local chosen = false

	local slugs = vim.tbl_keys(data.themes)
	table.sort(slugs)

	pickers
		.new({}, {
			prompt_title = "Theme",
			-- The previewer drives the live recoloring, and telescope drops the
			-- preview pane below preview_cutoff columns (120 by default), which
			-- would silently disable it in narrow windows. The palette pane is
			-- small, so always show it.
			layout_config = { preview_cutoff = 1, preview_width = 0.4 },
			finder = finders.new_table({
				results = slugs,
				entry_maker = function(slug)
					local t = data.themes[slug]
					return {
						value = slug,
						display = t.name .. (t.variant == "light" and "  (light)" or ""),
						ordinal = t.name,
					}
				end,
			}),
			sorter = conf.generic_sorter({}),
			-- The previewer's job is the side effect: recolor the whole editor
			-- as the selection moves. The pane itself lists the palette.
			previewer = previewers.new_buffer_previewer({
				title = "Palette",
				define_preview = function(self, entry)
					theme.apply(entry.value)
					local lines = { data.themes[entry.value].name, "" }
					local palette = data.themes[entry.value].palette
					local keys = vim.tbl_keys(palette)
					table.sort(keys)
					for _, k in ipairs(keys) do
						table.insert(lines, k .. "  " .. palette[k])
					end
					vim.api.nvim_buf_set_lines(self.state.bufnr, 0, -1, false, lines)
				end,
			}),
			attach_mappings = function(prompt_bufnr)
				actions.select_default:replace(function()
					local entry = action_state.get_selected_entry()
					chosen = true
					actions.close(prompt_bufnr)
					if entry then
						theme.apply(entry.value)
						run_theme_sync(entry.value, data.themes[entry.value].name)
					end
				end)
				actions.close:enhance({
					post = function()
						if not chosen and original then
							theme.apply(original)
						end
					end,
				})
				return true
			end,
		})
		:find()
end

return {
	"nvim-telescope/telescope.nvim",
	dependencies = { "nvim-lua/plenary.nvim" },
	keys = {
		{ "<leader>ff", "<cmd>Telescope find_files<cr>", desc = "Find files" },
		{ "<leader>fg", "<cmd>Telescope live_grep<cr>", desc = "Live grep" },
		{ "<leader>fb", "<cmd>Telescope buffers<cr>", desc = "Buffers" },
		{ "<leader>ft", pick_theme, desc = "Pick theme" },
	},
}
